export default {
  async fetch(request, env, ctx) {
    const cors = createCorsHeaders(request, env);

    if (request.method === "OPTIONS") {
      return new Response(null, { status: 204, headers: cors });
    }

    const origin = request.headers.get("Origin");
    if (origin && !isAllowedOrigin(origin, env)) {
      return jsonResponse({ ok: false, error: "許可されていないオリジンです。" }, 403, cors);
    }

    const url = new URL(request.url);
    const path = url.pathname.replace(/\/+$/, "") || "/";

    if (path === "/health" && request.method === "GET") {
      return noStoreJsonResponse({
        ok: true,
        service: "starting9-auth",
        database: "not_checked",
        generatedAt: new Date().toISOString()
      }, 200, cors);
    }

    if (!env.AUTH_DB) {
      return jsonResponse({ ok: false, error: "認証サービスが現在利用できません。" }, 503, cors);
    }

    try {
      const authRateLimitResponse = enforceAuthRateLimit(request, path, cors);
      if (authRateLimitResponse) return authRateLimitResponse;

      const adminMethodAuthResponse = await requireAdminAuthForMethodMismatch(request, env, cors, path);
      if (adminMethodAuthResponse) return adminMethodAuthResponse;

      if (path === "/api/auth/register" && request.method === "POST") {
        return await handleRegister(request, env, cors);
      }
      if (path === "/api/auth/login" && request.method === "POST") {
        return await handleLogin(request, env, cors);
      }
      if (path === "/api/auth/logout" && request.method === "POST") {
        return await handleLogout(request, env, cors);
      }
      if (path === "/api/auth/me" && request.method === "GET") {
        return await handleMe(request, env, ctx, cors);
      }
      const adminRankingRoute = /^\/api\/admin\/rankings\/(weekly|monthly|yearly)$/.exec(path);
      if (adminRankingRoute && request.method === "GET") {
        return await handleAdminRanking(request, env, cors, adminRankingRoute[1]);
      }
      if (path === "/api/me/achievements" && request.method === "GET") {
        return await handleMyAchievements(request, env, cors);
      }
      if (path === "/api/rankings/perfect" && request.method === "GET") {
        return await handleGetPerfectAchieversRanking(request, env, cors);
      }
      if (path === "/api/rankings/yearly" && request.method === "GET") {
        return await handleGetYearlyRanking(request, env, cors);
      }
      if (path === "/api/me/ranking/yearly" && request.method === "GET") {
        return await handleGetMyYearlyRanking(request, env, cors);
      }
      if (path === "/api/rankings/monthly" && request.method === "GET") {
        return await handleGetMonthlyRanking(request, env, cors);
      }
      if (path === "/api/me/ranking/monthly" && request.method === "GET") {
        return await handleGetMyMonthlyRanking(request, env, cors);
      }
      if (path === "/api/rankings/weekly" && request.method === "GET") {
        return await handleGetWeeklyRanking(request, env, cors);
      }
      if (path === "/api/me/ranking/weekly" && request.method === "GET") {
        return await handleGetMyWeeklyRanking(request, env, cors);
      }
      if (path === "/api/game-day-status" && request.method === "GET") {
        return await handleGetGameDayStatus(request, env, cors);
      }
      if (path === "/api/game-day-roster" && request.method === "GET") {
        return await handleGetGameDayRosterWithCache(request, env, ctx, cors);
      }
      if (path === "/api/prediction-target" && request.method === "GET") {
        return await handleGetPredictionTarget(request, env, cors);
      }
      if (path === "/api/public/games" && request.method === "GET") {
        return await handlePublicReadWithCache({
          request,
          env,
          ctx,
          cors,
          kind: "games",
          freshTtlSeconds: PUBLIC_GAMES_CACHE_FRESH_TTL_SECONDS,
          originHandler: () => handleGetPublicGames(request, env, cors)
        });
      }
      if (path === "/api/public/previous-result-game" && request.method === "GET") {
        return await handlePublicReadWithCache({
          request,
          env,
          ctx,
          cors,
          kind: "previous-result-game",
          freshTtlSeconds: PUBLIC_PREVIOUS_RESULT_CACHE_FRESH_TTL_SECONDS,
          originHandler: () => handleGetPreviousResultGame(request, env, cors)
        });
      }
      if (path === "/api/probable-starter" && request.method === "GET") {
        return await handleGetProbableStarter(request, env, cors);
      }
      const resultGameRoute = parseResultGameRoute(path);
      if (resultGameRoute && request.method === "GET") {
        return await handleGetResultGame(request, env, cors, resultGameRoute.gameId);
      }
      if (path === "/api/results/games" && request.method === "GET") {
        return await handleGetResultGames(request, env, cors);
      }
      if (path === "/api/results/daily-best-nine" && request.method === "GET") {
        return await handleGetDailyBestNine(request, env, cors);
      }
      if (path === "/api/admin/me" && request.method === "GET") {
        return await handleAdminMe(request, env, cors);
      }
      if (path === "/api/admin/push/status" && request.method === "GET") {
        return await handleAdminPushStatus(request, env, cors);
      }
      if (path === "/api/admin/push/test" && request.method === "POST") {
        return await handleAdminPushTest(request, env, cors);
      }
      if (path === "/api/admin/push/subscribe" && request.method === "POST") {
        return await handleAdminPushSubscribe(request, env, cors);
      }
      if (path === "/api/admin/push/unsubscribe" && request.method === "POST") {
        return await handleAdminPushUnsubscribe(request, env, cors);
      }
      if (path === "/api/admin/push/alerts" && request.method === "GET") {
        return await handleAdminPushAlerts(request, env, cors);
      }
      if (path === "/api/admin/v3/overview" && request.method === "GET") {
        return await handleAdminV3Overview(request, env, cors);
      }
      if (path === "/api/admin/v3/lineup-corrections" && request.method === "GET") {
        return await handleAdminV3LineupCorrectionsGet(request, env, cors);
      }
      if (path === "/api/admin/v3/manual-roster" && ["GET", "PUT"].includes(request.method)) {
        return await handleAdminV3ManualRoster(request, env, cors, ctx);
      }
      if (path === "/api/admin/v3/automation-logs" && request.method === "GET") {
        return await handleAdminV3AutomationLogs(request, env, cors);
      }
      if (path === "/api/admin/v3/ranking-resets" && request.method === "GET") {
        return await handleAdminV3RankingResetsGet(request, env, cors);
      }
      if (path === "/api/admin/v3/ranking-exclusion/games" && request.method === "GET") {
        return await handleAdminV3RankingExclusionGamesGet(request, env, cors);
      }
      if (path === "/api/admin/v3/ranking-resets/preview" && request.method === "POST") {
        return await handleAdminV3RankingResetPreview(request, env, cors);
      }
      if (path === "/api/admin/v3/schedule/add-game/preview" && request.method === "POST") {
        return await handleAdminV3ManualGamePreview(request, env, cors);
      }
      if (path === "/api/admin/v3/ranking-resets/execute" && request.method === "POST") {
        return await handleAdminV3RankingResetExecute(request, env, cors);
      }
      if (path === "/api/admin/maintenance/pre-beta-purge" && ["GET", "POST"].includes(request.method)) {
        return await handleAdminPreBetaPurge(request, env, cors);
      }
      if (path === "/api/admin/maintenance/pre-beta-purge/jobs" && request.method === "POST") {
        return await handleAdminPreBetaPurgeJobCleanup(request, env, cors);
      }
      if (path === "/api/admin/v3/perfect-score-test/preview") {
        if (request.method !== "POST") return jsonResponse({ ok: false, code: "V3_ADMIN_METHOD_NOT_ALLOWED", error: "満点previewはPOSTのみ対応しています。" }, 405, cors);
        return await handleAdminV3PerfectScorePreview(request, env, cors);
      }
      if (path === "/api/admin/v3/ranking-test-users/global") {
        return await handleAdminV3RankingTestGlobalSettings(request, env, cors);
      }
      if (path === "/api/admin/v3/ranking-test-users/name") {
        return await handleAdminV3RankingTestDisplayName(request, env, cors);
      }
      const adminV3RankingTestRoute = parseAdminV3RankingTestRoute(path);
      if (adminV3RankingTestRoute) {
        return await handleAdminV3RankingTestUsers(request, env, cors, adminV3RankingTestRoute);
      }
      const adminV3IdentityResolveRoute = parseAdminV3IdentityResolveRoute(path);
      if (adminV3IdentityResolveRoute && request.method === "POST") {
        return await handleAdminV3IdentityResolve(request, env, cors, adminV3IdentityResolveRoute.internalGameId);
      }
      const adminV3NpbGameCodeRoute = parseAdminV3NpbGameCodeRoute(path);
      if (adminV3NpbGameCodeRoute && request.method === "PATCH") {
        return await handleAdminV3NpbGameCodeUpdate(request, env, cors, adminV3NpbGameCodeRoute.internalGameId);
      }
      const adminV3OrientationRoute = parseAdminV3OrientationRoute(path);
      if (adminV3OrientationRoute && request.method === "PATCH") {
        return await handleAdminV3OrientationUpdate(request, env, cors, adminV3OrientationRoute.internalGameId);
      }
      const adminV3LineupRevisionCancelRoute = parseAdminV3LineupRevisionCancelRoute(path);
      if (adminV3LineupRevisionCancelRoute && request.method === "POST") {
        return await handleAdminV3LineupRevisionCancel(request, env, cors, adminV3LineupRevisionCancelRoute);
      }
      const adminV3LineupCorrectionRoute = parseAdminV3LineupCorrectionRoute(path);
      if (adminV3LineupCorrectionRoute) {
        return await handleAdminV3LineupCorrection(request, env, cors, adminV3LineupCorrectionRoute);
      }
      const adminV3Phase1Route = parseAdminV3Phase1Route(path);
      if (adminV3Phase1Route) {
        return await handleAdminV3Phase1Route(request, env, cors, adminV3Phase1Route);
      }
      const adminV3JobRoute = parseAdminV3JobRoute(path);
      if (adminV3JobRoute && request.method === "POST") {
        return await handleAdminV3JobCreate(request, env, cors, adminV3JobRoute.internalGameId);
      }
      const adminV3JobControlRoute = parseAdminV3JobControlRoute(path);
      if (adminV3JobControlRoute) {
        if (adminV3JobControlRoute.action === "diagnose" && request.method === "GET") {
          return await handleAdminV3JobDiagnose(request, env, cors, adminV3JobControlRoute.internalGameId);
        }
        if (adminV3JobControlRoute.action === "run" && request.method === "POST") {
          return await handleAdminV3JobCreate(request, env, cors, adminV3JobControlRoute.internalGameId);
        }
      }
      if ([
        "/api/admin/mode-capabilities",
        "/api/admin/automation/health",
        "/api/admin/game-progress-status",
        "/api/admin/workflow-logs",
        "/api/admin/audit/game-identities"
      ].includes(path)) {
        return await requireAndRetireLegacyAdminMutation(request, env, cors);
      }
      const gameIdentityRepairAuditRoute = parseGameIdentityRepairAuditRoute(path);
      if (gameIdentityRepairAuditRoute) {
        return await requireAndRetireLegacyAdminMutation(request, env, cors);
      }
      if (path === "/api/admin/audit/game-identity-repairs") {
        return await requireAndRetireLegacyAdminMutation(request, env, cors);
      }
      if (path === "/api/admin/game-identities/repairs") {
        return await requireAndRetireLegacyAdminMutation(request, env, cors);
      }
      const gameIdentityRepairRollbackRoute = parseGameIdentityRepairRollbackRoute(path);
      if (gameIdentityRepairRollbackRoute) {
        return await requireAndRetireLegacyAdminMutation(request, env, cors);
      }
      if (path === "/api/admin/audit/game-workflows") {
        return await requireAndRetireLegacyAdminMutation(request, env, cors);
      }
      const historicalGameWorkflowAuditRoute = parseHistoricalGameWorkflowAuditRoute(path);
      if (historicalGameWorkflowAuditRoute) {
        return await requireAndRetireLegacyAdminMutation(request, env, cors);
      }
      if (path === "/api/admin/audit/current-game-workflow") {
        return await requireAndRetireLegacyAdminMutation(request, env, cors);
      }
      if (path === "/api/admin/audit/release-readiness") {
        return await requireAndRetireLegacyAdminMutation(request, env, cors);
      }
      const probableStarterRefreshRoute = parseProbableStarterRefreshRoute(path);
      if (probableStarterRefreshRoute && request.method === "POST") {
        return await requireAndRetireLegacyAdminMutation(request, env, cors);
      }
      if (path === "/api/admin/automation/settings") {
        return await requireAndRetireLegacyAdminMutation(request, env, cors);
      }
      const adminScoringRoute = parseAdminScoringRoute(path);
      if (adminScoringRoute) {
        return await requireAndRetireLegacyAdminMutation(request, env, cors);
      }
      const autoScoringTestRoute = parseAutoScoringTestRoute(path);
      if (autoScoringTestRoute) {
        return await requireAndRetireLegacyAdminMutation(request, env, cors);
      }
      const adminTestGameRoute = parseAdminTestGameRoute(path);
      if (adminTestGameRoute) {
        return await requireAndRetireLegacyAdminMutation(request, env, cors);
      }
      if (path === "/api/perfect-achievers" && request.method === "GET") {
        return await handleGetPerfectAchievers(request, env, cors);
      }
      if (path === "/api/perfect-achievers" && request.method === "POST") {
        return await handlePostPerfectAchiever(request, env, cors);
      }
      if (path === "/api/predictions/current" && request.method === "GET") {
        return await handleGetCurrentPrediction(request, env, cors);
      }
      if (path === "/api/predictions/current" && request.method === "PUT") {
        return await handlePutCurrentPrediction(request, env, cors);
      }
      if (path === "/api/predictions/current" && request.method === "DELETE") {
        return await handleDeleteCurrentPrediction(request, env, cors);
      }

      return jsonResponse({ ok: false, error: "認証APIのパスまたはHTTPメソッドが不正です。" }, 404, cors);
    } catch (error) {
      if (error?.isRequestBodyError) {
        return jsonResponse({ ok: false, code: error.code, error: error.message }, error.httpStatus, cors);
      }
      const d1Failure = classifyD1ReadError(error);
      if (d1Failure) return createD1ReadFailureResponse(cors, d1Failure);
      const endpoint = url.pathname;
      const failureCode = String(error?.code || "AUTH_API_INTERNAL_ERROR");
      const failureDetail = String(error?.message || "").replace(/[\r\n]+/g, " ").slice(0, 240);
      const predictionRoute = path === "/api/predictions/current";
      const routeFailureCode = predictionRoute
        ? (request.method === "GET" ? "PREDICTION_READ_FAILED" : request.method === "DELETE" ? "PREDICTION_DELETE_FAILED" : "PREDICTION_SAVE_FAILED")
        : failureCode;
      console.error(`[AUTH_API] endpoint=${endpoint} authenticated=unknown userId= resolvedRole= failureCode=${routeFailureCode} detail=${failureDetail}`);
      return jsonResponse({
        ok: false,
        code: routeFailureCode,
        error: predictionRoute ? "アカウント予想の保存処理に失敗しました。" : "認証処理に失敗しました。"
      }, 500, cors);
    }
  },

  async scheduled(event, env, ctx) {
    const scheduledAt = new Date(Number(event?.scheduledTime) || Date.now());
    const invocationAt = new Date();
    const runId = globalThis.crypto?.randomUUID?.() || `v3-run-${Date.now()}`;
    const cronMode = resolveV3CronMode(event?.cron);
    const isCriticalCron = cronMode === "critical";
    if (isCriticalCron) ctx.waitUntil(writeCronHeartbeatSafely(env, recordCronInvocation, invocationAt, "invocation"));
    const flags = {
      cronMode,
      enabled: isGameAutomationV3Enabled(env),
      gameAutomationV3: String(env?.ENABLE_GAME_AUTOMATION_V3 || ""),
      workflowCompletionJobs: String(env?.ENABLE_WORKFLOW_COMPLETION_JOBS || ""),
      npbFetchDisabled: String(env?.NPB_FETCH_DISABLED || ""),
      now: scheduledAt.toISOString()
    };
    if (isCriticalCron) {
      ctx.waitUntil(writeV3RuntimeAudit(env, {
        eventType: "CRON_HANDLER_STARTED",
        runId,
        correlationId: runId,
        now: scheduledAt,
        execution: { stage: "cron_handler_started", scheduledAt: scheduledAt.toISOString() }
      }));
      ctx.waitUntil(writeV3RuntimeAudit(env, {
        eventType: "CRON_HANDLER_FLAGS",
        runId,
        correlationId: runId,
        now: scheduledAt,
        execution: { stage: "cron_handler_flags", ...flags }
      }));
    }
    logV3PhaseCheckpoint(runId, { stage: "cron_started", now: scheduledAt, status: "started" }, scheduledAt);
    if (!env.AUTH_DB) {
      console.error("auto scoring skipped: AUTH_DB binding is unavailable");
      if (isCriticalCron) ctx.waitUntil(writeV3RuntimeAudit(env, {
        eventType: "CRON_HANDLER_FINISHED",
        runId,
        correlationId: runId,
        now: scheduledAt,
        execution: { stage: "cron_handler_finished", status: "skipped", reasonCode: "AUTH_DB_UNAVAILABLE" }
      }));
      return;
    }
    if (!flags.enabled) {
      console.info(`[GAME_AUTOMATION_V3] enabled=false flag=${V3_FEATURE_FLAG} action=skip`);
      if (isCriticalCron) ctx.waitUntil(writeCronHeartbeatSafely(env, recordCronCompleted, new Date(), "completed"));
      if (isCriticalCron) ctx.waitUntil(writeV3RuntimeAudit(env, {
        eventType: "CRON_HANDLER_FINISHED",
        runId,
        correlationId: runId,
        now: scheduledAt,
        execution: { stage: "cron_handler_finished", status: "skipped", reasonCode: "V3_FEATURE_DISABLED" }
      }));
      return;
    }
    const formalRun = runScheduledGameAutomationV3(env, scheduledAt, {
      runId,
      mode: cronMode,
      scheduleOptional: (promise) => ctx.waitUntil(promise),
      observerScheduler: (promise) => ctx.waitUntil(promise)
    });
    ctx.waitUntil(formalRun.then(
      async (result) => {
        if (isCriticalCron) await writeCronHeartbeatSafely(env, recordCronCompleted, new Date(), "completed");
        return result;
      },
      async (error) => {
        if (isCriticalCron) await writeCronHeartbeatSafely(env, recordCronFailed, new Date(), "failed");
        throw error;
      }
    ));
  }
};

function getV3AuditDb(env) {
  return env?.AUDIT_DB || null;
}

async function writeCronHeartbeatSafely(env, operation, now, phase) {
  try {
    if (!env?.AUTH_DB) throw new Error("CRON_HEARTBEAT_DB_UNAVAILABLE");
    await operation(env.AUTH_DB, now);
  } catch (error) {
    // Heartbeat is observability only. A schema rollout or transient D1
    // failure must never change formal job execution semantics.
    console.warn(`[GAME_AUTOMATION_V3] cron_heartbeat status=skipped phase=${phase} code=${error?.code || error?.message || "CRON_HEARTBEAT_WRITE_FAILED"}`);
  }
}

export function buildV3RosterMonitor(games = [], { teamCode = FIGHTERS_TEAM_CODE, manualRoster = null } = {}) {
  const normalizedTeam = String(teamCode || FIGHTERS_TEAM_CODE).trim().toLowerCase();
  const targets = (Array.isArray(games) ? games : []).filter((game) => {
    const teams = [game?.homeTeam, game?.awayTeam, game?.home_team, game?.away_team]
      .map((value) => String(value || "").trim().toLowerCase());
    return teams.includes(normalizedTeam) || (normalizedTeam === "fighters" && teams.includes("f"));
  });
  const diagnostics = targets.map((game) => game?.rosterDiagnostics || {}).sort((left, right) => {
    const leftAt = new Date(left.sourceFetchedAt || left.fetchedAt || left.rosterSnapshotCapturedAt || 0).getTime();
    const rightAt = new Date(right.sourceFetchedAt || right.fetchedAt || right.rosterSnapshotCapturedAt || 0).getTime();
    return rightAt - leftAt;
  });
  const latest = diagnostics[0] || {};
  const manualEntries = Array.isArray(manualRoster?.entries) ? manualRoster.entries : [];
  const activeCount = manualEntries.filter((entry) => String(entry?.status || "active").toLowerCase() === "active").length;
  const inactiveCount = manualEntries.filter((entry) => String(entry?.status || "").toLowerCase() === "inactive").length;
  const hasError = diagnostics.some((entry) => String(entry.severity || "").toUpperCase() === "ERROR" || Boolean(entry.publicCandidateWarning && entry.isSnapshotStale));
  const hasWarning = diagnostics.some((entry) => Boolean(entry.isSnapshotStale || entry.publicCandidateWarning || entry.reasonCode));
  const source = latest.publicCandidateSource || latest.rosterSnapshotSource || (latest.rosterSnapshotExists ? "snapshot" : "none");
  const status = hasError ? "ERROR" : hasWarning ? "WARN" : source === "none" ? "WARN" : "OK";
  const lastCheckedAt = latest.sourceFetchedAt || latest.fetchedAt || latest.rosterSnapshotCapturedAt || null;
  const lastSuccessfulAt = diagnostics.find((entry) => entry.rosterSnapshotExists && !entry.isSnapshotStale)?.rosterSnapshotCapturedAt || null;
  const lastChangedAt = diagnostics.find((entry) => entry.previousSnapshotComparison?.mismatch)?.sourceFetchedAt
    || diagnostics.find((entry) => Number(entry.totalRosterChanges || 0) > 0)?.fetchedAt || null;
  const playerCount = Number(latest.publicCandidateOfficialPlayerCount ?? latest.rosterSnapshotPlayerCount ?? 0) || 0;
  return {
    teamCode: normalizedTeam,
    status,
    source,
    lastCheckedAt,
    lastSuccessfulAt,
    lastChangedAt,
    playerCount,
    candidateCount: manualRoster?.schemaAvailable === false ? null : activeCount,
    rosterOutCandidateCount: manualRoster?.schemaAvailable === false ? null : inactiveCount,
    fallback: /fallback|stale|baseline|static|none/i.test(String(source || "")),
    manualRosterSource: manualRoster?.source || null,
    manualRosterSaved: manualRoster?.isManualSaved === true,
    gameCount: targets.length,
    warning: latest.publicCandidateWarning || latest.staleReason || (source === "none" ? "公式ロースターをまだ確認できていません。" : null)
  };
}

async function writeV3RuntimeAudit(env, { eventType, runId, correlationId = runId, now = new Date(), internalGameId = null, execution = null, failure = null } = {}) {
  try {
    if (!shouldPersistV3Audit({ eventType, execution, failure })) return false;
    const auditDb = getV3AuditDb(env);
    if (!env?.AUTH_DB || !auditDb) {
      console.warn(`[GAME_AUTOMATION_V3] runtime_audit_skipped code=AUDIT_DB_UNAVAILABLE event=${eventType || "unknown"}`);
      return false;
    }
    const anchor = internalGameId || (await env.AUTH_DB.prepare(
      `SELECT internal_game_id FROM games WHERE internal_game_id IS NOT NULL AND internal_game_id <> '' ORDER BY game_date, start_time, internal_game_id LIMIT 1`
    ).first())?.internal_game_id;
    if (!anchor) {
      console.warn(`[GAME_AUTOMATION_V3] runtime_audit_skipped code=NO_GAME_AUDIT_ANCHOR event=${eventType || "unknown"}`);
      return false;
    }
    const auditColumns = await getTableColumnSet(auditDb, "game_automation_v3_audit");
    const { columns, values } = buildV3CronJobAuditInsert({
      auditColumns,
      runId,
      correlationId,
      eventType,
      internalGameId: anchor,
      job: { internal_game_id: anchor, job_type: "cron_run", status: failure ? "failed" : "completed" },
      execution,
      failure,
      occurredAt: now,
      now
    });
    await auditDb.prepare(
      `INSERT INTO game_automation_v3_audit (${columns.join(", ")}) VALUES (${columns.map((_, index) => `?${index + 1}`).join(", ")})`
    ).bind(...values).run();
    return true;
  } catch (error) {
    console.error(`[GAME_AUTOMATION_V3] runtime_audit_failed event=${eventType || "unknown"} code=${error?.code || "V3_RUNTIME_AUDIT_FAILED"}`);
    return false;
  }
}

const ROSTER_MASTER_WARNING_DEDUPE_WINDOW_MS = 5 * 60 * 1000;
const V3_CRON_GAME_BATCH_SIZE = 4;
// 補助処理は当日最大6試合と翌日最大6試合を毎分確認すれば、
// 予告先発の前日slotを取りこぼさず、過去の未完了試合を無制限に走査して
// CronのCPU上限を消費することも防げます。正式処理のbatchとは分離します。
const V3_AUXILIARY_GAME_BATCH_SIZE = 12;

function isProductionRuntime(env = {}) {
  return [env?.ENVIRONMENT, env?.APP_ENV, env?.NODE_ENV].some((value) => ["production", "prod"].includes(String(value || "").trim().toLowerCase()))
    || String(env?.ENABLE_DEVELOPMENT_MODE || "").trim().toLowerCase() === "false";
}

function parseLineupShadowMetadata(value) {
  if (!value || typeof value !== "string") return {};
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

function shadowRevisionStatus(row) {
  const payload = parseLineupShadowMetadata(row?.validation_json);
  const validation = payload.validation && typeof payload.validation === "object" ? payload.validation : {};
  return {
    status: String(payload.lifecycleStatus || (validation.ok ? "verified" : "invalid_lineup")),
    source: String(payload.source || row?.source || "official"),
    fetchedAt: row?.captured_at || row?.created_at || null,
    playerCount: Number(validation.playerCount || validation.parsedCount || 0),
    validationStatus: validation.status || (validation.ok ? "verified" : null),
    lineup: parseStoredActualLineup(row?.actual_lineup_json)
  };
}

async function readLineupShadowStatus(db, internalGameId, { enabled = false } = {}) {
  const result = {
    enabled,
    status: enabled ? "waiting" : "disabled",
    source: "official",
    fetchedAt: null,
    playerCount: 0,
    validationStatus: null,
    nextRetryAt: null,
    finalLineupExists: false,
    manualFinalExists: false,
    comparison: null,
    reasonCode: null
  };
  if (!db || !internalGameId) return result;
  try {
    const [revisions, logs] = await db.batch([
      db.prepare(
        `SELECT revision_id, version, actual_lineup_json, source, captured_at, created_at,
                is_final, validation_json
           FROM game_lineup_revisions
          WHERE internal_game_id = ?1
          ORDER BY version DESC LIMIT 50`
      ).bind(internalGameId),
      db.prepare(
        `SELECT status, occurred_at, error_code, metadata
           FROM game_workflow_logs
          WHERE game_id = ?1 AND event_type = 'lineup_shadow'
          ORDER BY occurred_at DESC LIMIT 5`
      ).bind(internalGameId)
    ]);
    const rows = revisions?.results || [];
    const manualFinal = rows.find((row) => Number(row.is_final || 0) === 1
      && ["manual", "manual-revision", "restore"].includes(String(row.source || "").trim().toLowerCase()));
    const final = rows.find((row) => Number(row.is_final || 0) === 1);
    const shadowRows = rows.filter((row) => Number(row.is_final || 0) !== 1 && isShadowLineupRevision(row));
    const latestShadow = shadowRows[0] ? shadowRevisionStatus(shadowRows[0]) : null;
    const latestLog = (logs?.results || [])[0] || null;
    const logMetadata = parseLineupShadowMetadata(latestLog?.metadata);
    result.finalLineupExists = Boolean(final);
    result.manualFinalExists = Boolean(manualFinal);
    if (manualFinal) {
      result.status = "manual_final_exists";
      result.fetchedAt = latestShadow?.fetchedAt || logMetadata.fetchedAt || null;
    } else if (latestLog) {
      result.status = String(logMetadata.status || latestLog.status || "waiting");
      result.fetchedAt = logMetadata.fetchedAt || latestLog.occurred_at || latestShadow?.fetchedAt || null;
      result.nextRetryAt = logMetadata.nextRetryAt || null;
      result.reasonCode = logMetadata.reasonCode || latestLog.error_code || null;
    } else if (latestShadow) {
      result.status = latestShadow.status;
      result.fetchedAt = latestShadow.fetchedAt;
    }
    if (latestShadow) {
      result.source = latestShadow.source;
      result.playerCount = latestShadow.playerCount;
      result.validationStatus = latestShadow.validationStatus;
    }
    const comparisonShadow = manualFinal ? selectShadowRevisionForComparison(rows, manualFinal) : null;
    if (manualFinal && comparisonShadow) {
      result.comparison = compareShadowLineupToManual(comparisonShadow.lineup, parseStoredActualLineup(manualFinal.actual_lineup_json));
    }
    return result;
  } catch (error) {
    if (!isPregameSchemaError(error)) console.warn(`[LINEUP_SHADOW] stage=status_read code=${error?.code || "SHADOW_STATUS_READ_FAILED"}`);
    return { ...result, status: "unavailable", reasonCode: "SHADOW_STATUS_UNAVAILABLE" };
  }
}

// Accuracy is an admin read model, not a new workflow artifact. Keep the
// history bounded so an overview refresh cannot turn old shadow revisions into
// the Cron hot path or require a migration. Manual/final and shadow rows are
// compared from their existing revision lineage only.
async function readLineupShadowAccuracy(db, now = new Date(), { enabled = true } = {}) {
  if (!db) return { available: false, code: "LINEUP_SHADOW_ACCURACY_DB_UNAVAILABLE", games: [], metrics: buildLineupShadowAccuracyReport([]).metrics };
  const current = now instanceof Date ? now : new Date(now);
  const today = getJstDateString(current);
  if (!today) return { available: false, code: "LINEUP_SHADOW_ACCURACY_DATE_UNAVAILABLE", games: [], metrics: buildLineupShadowAccuracyReport([]).metrics };
  try {
    const gameRows = await db.prepare(
      `SELECT internal_game_id, game_date, start_time, home_team, away_team,
              npb_game_code, game_status, is_active, deleted_at
         FROM games
        WHERE internal_game_id IS NOT NULL AND internal_game_id <> ''
          AND is_active = 1 AND deleted_at IS NULL
          AND (LOWER(COALESCE(home_team, '')) IN ('f', 'fighters')
            OR LOWER(COALESCE(away_team, '')) IN ('f', 'fighters'))
          AND date(game_date) BETWEEN date(?1, ?2) AND date(?1, '+1 day')
        ORDER BY date(game_date) DESC, start_time DESC, internal_game_id DESC
        LIMIT ?3`
    ).bind(today, `-${LINEUP_SHADOW_ACCURACY_LOOKBACK_DAYS} day`, LINEUP_SHADOW_ACCURACY_LIMIT).all();
    const games = gameRows?.results || [];
    const records = [];
    for (const game of games) {
      let revisions = [];
      let logs = [];
      try {
        const result = await db.batch([
          db.prepare(
            `SELECT revision_id, version, actual_lineup_json, source, captured_at,
                    created_at, finalized_at, is_final, validation_json, lineup_fingerprint
               FROM game_lineup_revisions
              WHERE internal_game_id = ?1
              ORDER BY version DESC LIMIT 50`
          ).bind(game.internal_game_id),
          db.prepare(
            `SELECT status, occurred_at, error_code, metadata
               FROM game_workflow_logs
              WHERE game_id = ?1 AND event_type = 'lineup_shadow'
              ORDER BY occurred_at DESC LIMIT 30`
          ).bind(game.internal_game_id)
        ]);
        revisions = result?.[0]?.results || [];
        logs = result?.[1]?.results || [];
      } catch (error) {
        console.warn(`[LINEUP_SHADOW_ACCURACY] game=${game.internal_game_id} stage=history_read code=${error?.code || "LINEUP_SHADOW_HISTORY_READ_FAILED"}`);
      }
      records.push(buildLineupShadowAccuracyRecord({
        game: {
          internalGameId: game.internal_game_id,
          gameDate: game.game_date,
          startAt: game.start_time,
          homeTeam: game.home_team,
          awayTeam: game.away_team,
          npbGameCode: game.npb_game_code,
          gameStatus: game.game_status
        },
        revisions,
        logs
      }));
    }
    return buildLineupShadowAccuracyReport(records, {
      limit: LINEUP_SHADOW_ACCURACY_LIMIT,
      lookbackDays: LINEUP_SHADOW_ACCURACY_LOOKBACK_DAYS,
      games,
      now,
      enabled
    });
  } catch (error) {
    console.warn(`[LINEUP_SHADOW_ACCURACY] stage=game_read code=${error?.code || "LINEUP_SHADOW_ACCURACY_READ_FAILED"}`);
    return {
      available: false,
      code: error?.code || "LINEUP_SHADOW_ACCURACY_READ_FAILED",
      games: [],
      metrics: buildLineupShadowAccuracyReport([]).metrics
    };
  }
}

function shadowObservationStatus(result) {
  if (result?.status === "verified") return "verified";
  if (["invalid_lineup", "unknown_player", "ambiguous_player", "identity_mismatch"].includes(result?.status)) return result.status;
  if (["cancelled", "no_game", "manual_final_exists"].includes(result?.status)) return result.status;
  if (result?.status === "not_published") return "waiting";
  return "temporary_failure";
}

async function runLineupShadowForGames(env, now, { runId = "" } = {}) {
  const summary = { status: "disabled", considered: 0, fetched: 0, verified: 0, waiting: 0, invalid: 0, skipped: 0, errors: 0, gameIds: [] };
  if (!isLineupShadowEnabled(env)) return summary;
  if (isProductionRuntime(env) && resolveNpbSource(env).kind !== "official") {
    return { ...summary, status: "blocked", reasonCode: "PRODUCTION_OFFICIAL_SOURCE_REQUIRED" };
  }
  const games = await listV3LineupShadowCandidates(env.AUTH_DB, now, { limit: 4 });
  summary.status = "completed";
  summary.considered = games.length;
  for (const game of games) {
    const target = {
      internalGameId: game.internalGameId,
      gameDate: game.gameDate,
      startAt: game.startAt,
      homeTeam: game.homeTeam,
      awayTeam: game.awayTeam,
      npbGameCode: game.npbGameCode,
      npbGameUrl: game.npbGameUrl,
      status: game.gameStatus
    };
    if (!isLineupShadowDue(target, now).due) {
      summary.skipped += 1;
      continue;
    }
    const current = await readLineupShadowStatus(env.AUTH_DB, game.internalGameId, { enabled: true });
    if (current.manualFinalExists || current.finalLineupExists || !shouldRetryLineupShadow(current, now)) {
      summary.skipped += 1;
      continue;
    }
    summary.gameIds.push(game.internalGameId);
    try {
      const result = await runLineupCandidatePipeline({
        env,
        target,
        db: env.AUTH_DB,
        autoFinalEnabled: false,
        shadowMode: true,
        now,
        fetchOfficial: async ({ target: fetchTarget, signal }) => {
          const payload = await fetchNpbWorkerJson(env, {
            mode: "lineup",
            url: fetchTarget.npbGameUrl || undefined,
            date: fetchTarget.gameDate,
            gameCode: fetchTarget.npbGameCode,
            homeTeam: fetchTarget.homeTeam,
            awayTeam: fetchTarget.awayTeam,
            startAt: fetchTarget.startAt
          }, { signal });
          return {
            ok: true,
            payload,
            httpStatus: payload?.__fetchMeta?.httpStatus || null,
            sourceUrl: payload?.sourceUrl || fetchTarget.npbGameUrl || null
          };
        }
      });
      const status = shadowObservationStatus(result);
      const nextRetryAt = nextLineupShadowRetryAt({ status }, now);
      const observation = buildLineupShadowObservation({
        status,
        source: result.source || "official",
        fetchedAt: result.candidate?.fetchedAt || result.fetchedAt || now.toISOString(),
        playerCount: result.validation?.playerCount || result.candidate?.lineup?.length || 0,
        validationStatus: result.validation?.status || result.code || null,
        reasonCode: result.code || null,
        nextRetryAt
      });
      await recordWorkflowLog(env.AUTH_DB, {
        eventType: "lineup_shadow",
        status: status === "verified" || status === "manual_final_exists" ? "success" : status === "waiting" || status === "temporary_failure" ? "info" : "warning",
        gameId: game.internalGameId,
        occurredAt: now,
        message: `lineup shadow: ${status}`,
        errorCode: result.code || "",
        metadata: { ...observation, runId, internalGameId: game.internalGameId, gameDate: game.gameDate },
        source: "cron"
      });
      if (status === "verified") summary.verified += 1;
      else if (status === "waiting" || status === "temporary_failure") summary.waiting += 1;
      else summary.invalid += 1;
    } catch (error) {
      summary.errors += 1;
      await recordWorkflowLog(env.AUTH_DB, {
        eventType: "lineup_shadow",
        status: "warning",
        gameId: game.internalGameId,
        occurredAt: now,
        message: "lineup shadow failed",
        errorCode: error?.code || "LINEUP_SHADOW_FAILED",
        metadata: { status: "temporary_failure", source: "official", reasonCode: error?.code || "LINEUP_SHADOW_FAILED", nextRetryAt: nextLineupShadowRetryAt({ status: "temporary_failure" }, now), runId, internalGameId: game.internalGameId, gameDate: game.gameDate },
        source: "cron"
      });
    }
  }
  return summary;
}

async function writeRosterMasterUnregisteredAudit(env, game, unknownPlayers, now = new Date()) {
  const internalGameId = String(game?.internal_game_id || game?.internalGameId || "").trim();
  const players = Array.isArray(unknownPlayers) ? unknownPlayers : [];
  if (!internalGameId || players.length === 0) return false;
  try {
    const auditDb = getV3AuditDb(env);
    if (!auditDb) return false;
    const auditColumns = await getTableColumnSet(auditDb, "game_automation_v3_audit");
    if (!auditColumns.has("event_type")) return false;
    const cutoff = new Date(now.getTime() - ROSTER_MASTER_WARNING_DEDUPE_WINDOW_MS).toISOString();
    const recent = await auditDb.prepare(
      `SELECT id FROM game_automation_v3_audit
         WHERE internal_game_id = ?1 AND event_type = ?2 AND occurred_at > ?3
         ORDER BY occurred_at DESC LIMIT 1`
    ).bind(internalGameId, "ROSTER_MASTER_UNREGISTERED", cutoff).first();
    if (recent) return false;
    return await writeV3RuntimeAudit(env, {
      eventType: "ROSTER_MASTER_UNREGISTERED",
      runId: `roster-master-${internalGameId}-${now.getTime()}`,
      correlationId: internalGameId,
      internalGameId,
      now,
      execution: {
        stage: "roster_master_check",
        status: "warning",
        reasonCode: "MASTER_UNREGISTERED",
        unknownCount: players.length,
        unknownPlayers: players.slice(0, 20).map((player) => ({
          playerId: player.playerId || null,
          name: player.name || null,
          number: player.number || null,
          position: player.position || null
        }))
      }
    });
  } catch (error) {
    console.warn(`[PUBLIC_ROSTER] master_warning_audit_skipped code=${error?.code || "ROSTER_MASTER_AUDIT_FAILED"}`);
    return false;
  }
}

async function collectAdminAlertGames(db, internalGameIds) {
  const ids = [...new Set((Array.isArray(internalGameIds) ? internalGameIds : []).map((id) => String(id || "").trim()).filter(Boolean))].slice(0, 8);
  if (!ids.length) return [];
  const placeholders = ids.map((_, index) => `?${index + 1}`).join(", ");
  const result = await db.prepare(
    `SELECT internal_game_id, game_date, start_time, home_team, away_team, game_status, npb_game_code
       FROM games WHERE internal_game_id IN (${placeholders})`
  ).bind(...ids).all();
  return (result.results || []).map((row) => ({
    internalGameId: row.internal_game_id,
    gameDate: row.game_date,
    startAt: row.start_time,
    homeTeam: row.home_team,
    awayTeam: row.away_team,
    gameStatus: row.game_status,
    npbGameCode: row.npb_game_code || null
  }));
}

async function buildAdminAlertSignals(db, env, game, now) {
  const [stateRow, jobsResult] = await Promise.all([
    db.prepare("SELECT state FROM game_automation_v3_state WHERE internal_game_id = ?1 LIMIT 1").bind(game.internalGameId).first(),
    db.prepare(
      `SELECT job_type, status, scheduled_at, scheduled_slot_at, attempt_count, max_attempts,
              next_retry_at, failure_code, updated_at
         FROM game_jobs_v3 WHERE internal_game_id = ?1
        ORDER BY COALESCE(updated_at, scheduled_at) DESC, id DESC LIMIT 40`
    ).bind(game.internalGameId).all()
  ]);
  const workflowState = String(stateRow?.state || "scheduled");
  const workflowArtifactHealth = await getV3WorkflowArtifactHealth(db, game.internalGameId, workflowState).catch(() => null);
  const jobs = jobsResult.results || [];
  const schedule = deriveV3DisplaySchedule(game);
  const notTerminal = !["published", "cancelled", "canceled", "postponed", "no_game", "service_unavailable", "excluded"].includes(workflowState);
  const latest = (types) => jobs.find((job) => types.includes(String(job.job_type || ""))) || null;
  const closeJob = latest(["prediction_close"]);
  const closeDeadline = new Date(schedule.predictionDeadline).getTime();
  const graceElapsed = Number.isFinite(closeDeadline) && closeDeadline + 5 * 60 * 1000 <= now.getTime();
  const closeCompleted = closeJob?.status === "completed";
  const phases = {
    score: deriveV3PhaseStatus({ phase: "score", game, now, workflowState, jobs, workflowArtifactHealth }),
    ranking: deriveV3PhaseStatus({ phase: "ranking", game, now, workflowState, jobs, workflowArtifactHealth }),
    publish: deriveV3PhaseStatus({ phase: "publish", game, now, workflowState, jobs, workflowArtifactHealth })
  };
  const attentionFailure = (phase) => phase?.severity === "ATTENTION"
    && (phase.failedJobExists === true || /FAILED|INVALID|MISMATCH|INTEGRITY|UNEXPECTED|EXHAUSTED/.test(String(phase.reasonCode || "")));
  const lineupRequired = ["prediction_closed", "lineup_ready", "scored", "ranked", "published", "manual_action_required"].includes(workflowState);
  const finalLineupAt = new Date(schedule.finalLineupAt).getTime();
  const manualLineupOverdue = String(env.ENABLE_SEMI_AUTO_LINEUP || "").toLowerCase() === "true"
    && ["prediction_closed", "manual_action_required"].includes(workflowState)
    && lineupRequired
    && (workflowArtifactHealth?.lineup?.available !== true || workflowArtifactHealth.lineup.ready !== true)
    && Number.isFinite(finalLineupAt)
    && finalLineupAt + 30 * 60 * 1000 <= now.getTime();
  const canonicalLineupInvalid = lineupRequired
    && workflowState !== "prediction_closed"
    && workflowArtifactHealth?.lineup?.available === true
    && workflowArtifactHealth.lineup.ready !== true
    && (phases.score?.severity === "ATTENTION" || phases.ranking?.severity === "ATTENTION" || phases.publish?.severity === "ATTENTION");
  const scoringArtifactInvalid = ["scored", "ranked", "published"].includes(workflowState)
    && workflowArtifactHealth?.scoring?.available === true
    && workflowArtifactHealth.scoring.ready !== true
    && phases.score?.severity === "ATTENTION";
  return {
    manualLineupOverdue,
    predictionCloseOverdue: notTerminal && graceElapsed && !closeCompleted && Boolean(closeJob),
    missingDueJob: notTerminal && graceElapsed && !closeCompleted && !closeJob && workflowState === "scheduled",
    scoreFailure: attentionFailure(phases.score),
    rankingFailure: attentionFailure(phases.ranking),
    publishFailure: attentionFailure(phases.publish),
    canonicalLineupInvalid,
    scoringArtifactInvalid,
    rankingRevisionMismatch: phases.ranking?.severity === "ATTENTION" && /MISMATCH/.test(String(phases.ranking.reasonCode || "")),
    publicationInvalid: workflowState === "published" && phases.publish?.severity === "ATTENTION",
    // Phase 5/5.5 production flags remain disabled; the future signals are
    // intentionally not synthesized here and therefore cannot page operators.
    gameCodeAmbiguous: false,
    gameCodeTemporaryFailure: false,
    additionalScheduleReview: false
  };
}

function scheduleAdminAlertEvaluation(env, now, result, observerScheduler) {
  if (!env?.AUTH_DB || !Array.isArray(result?.gameIds) || !result.gameIds.length) return Promise.resolve();
  const task = Promise.resolve().then(async () => evaluateAndNotifyAdminAlerts({
    db: env.AUTH_DB,
    env,
    now,
    games: await collectAdminAlertGames(env.AUTH_DB, result.gameIds),
    getSignals: (game) => buildAdminAlertSignals(env.AUTH_DB, env, game, now),
    log: (message) => console.warn(message)
  })).catch((error) => {
    console.warn(`[ADMIN_ALERT] stage=cron_evaluation code=${error?.code || "ADMIN_ALERT_EVALUATION_FAILED"}`);
    return { ok: false, skipped: "ADMIN_ALERT_EVALUATION_FAILED" };
  });
  if (typeof observerScheduler === "function") observerScheduler(task);
  return task;
}

async function runScheduledGameAutomationV3(env, now, { runId: providedRunId = null, scheduleOptional = null, observerScheduler = null, mode = "combined" } = {}) {
  const criticalOnly = mode === "critical";
  const auxiliaryOnly = mode === "auxiliary";
  const runId = providedRunId || globalThis.crypto?.randomUUID?.() || `v3-run-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const correlationId = runId;
  await writeV3RuntimeAudit(env, {
    eventType: "V3_RUN_STARTED",
    runId,
    correlationId,
    now,
    execution: { stage: "v3_run_started", now: now.toISOString() }
  });
  const writeAudit = async ({ eventType = "job", job, internalGameId = null, claimToken = null, stateBefore = null, execution = null, failure = null, occurredAt = now } = {}) => {
    if (!shouldPersistV3Audit({ eventType, job, execution, failure })) return false;
    const auditDb = getV3AuditDb(env);
    if (!auditDb) return false;
    try {
      const auditColumns = await getTableColumnSet(auditDb, "game_automation_v3_audit");
      const { columns, values } = buildV3CronJobAuditInsert({
        auditColumns,
        runId,
        correlationId,
        eventType,
        job,
        internalGameId,
        claimToken,
        stateBefore,
        execution,
        failure,
        occurredAt,
        now
      });
      await auditDb.prepare(
        `INSERT INTO game_automation_v3_audit (${columns.join(", ")})
         VALUES (${columns.map((_, index) => `?${index + 1}`).join(", ")})`
      ).bind(...values).run();
      return true;
    } catch (error) {
      console.warn(`[GAME_AUTOMATION_V3] audit_write_skipped code=${error?.code || "V3_AUDIT_WRITE_FAILED"}`);
      return false;
    }
  };
  const cronCriticalPathAuditState = { recorded: false };
  const writeCronCriticalPathFinished = async (status, details = {}) => {
    return writeV3TerminalAuditOnce(
      (payload) => writeV3RuntimeAudit(env, payload),
      cronCriticalPathAuditState,
      {
        eventType: "CRON_CRITICAL_PATH_FINISHED",
        runId,
        correlationId,
        now,
        execution: { stage: "cron_critical_path_finished", status, ...details }
      }
    );
  };
  const writeCriticalPathFinished = auxiliaryOnly
    ? async () => false
    : writeCronCriticalPathFinished;
  const cronHandlerAuditState = { recorded: false };
  const writeCronHandlerFinished = async (status, details = {}) => {
    logV3PhaseCheckpoint(runId, { stage: "cron_finished", now, status, ...details }, now);
    return writeV3TerminalAuditOnce(
      (payload) => writeV3RuntimeAudit(env, payload),
      cronHandlerAuditState,
      {
        eventType: "CRON_HANDLER_FINISHED",
        runId,
        correlationId,
        now,
        execution: { stage: "cron_handler_finished", status, ...details }
      }
    );
  };

  const writeScheduleSyncAudit = async (diagnostics) => {
    if (!shouldPersistV3Audit({ eventType: "schedule_sync", execution: diagnostics })) return;
    const auditDb = getV3AuditDb(env);
    if (!auditDb) return;
    try {
      const anchor = await env.AUTH_DB.prepare(
        `SELECT internal_game_id
           FROM games
          WHERE internal_game_id IS NOT NULL AND internal_game_id <> ''
          ORDER BY game_date, start_time, internal_game_id
          LIMIT 1`
      ).first();
      if (!anchor?.internal_game_id) return;
      const auditColumns = await getTableColumnSet(auditDb, "game_automation_v3_audit");
      const { columns, values } = buildV3ScheduleSyncAuditInsert({
        auditColumns,
        internalGameId: anchor.internal_game_id,
        diagnostics,
        runId,
        correlationId,
        now
      });
      await auditDb.prepare(
        `INSERT INTO game_automation_v3_audit (${columns.join(", ")})
         VALUES (${columns.map((_, index) => `?${index + 1}`).join(", ")})`
      ).bind(...values).run();
    } catch (error) {
      console.warn(`[GAME_AUTOMATION_V3] stage=schedule_sync_audit status=skipped code=${error?.code || "V3_SCHEDULE_SYNC_AUDIT_FAILED"}`);
    }
  };

  // Schedule synchronization can fan out across the lookahead window and
  // wait on the external NPB service. Keep the normal bounded sync first, then
  // reconcile the statuses it just observed in the same run. This makes a
  // simulator no-game/cancellation response reach the existing eligibility
  // gate without adding an extra scan or a second external fetch.
  const runScheduleSync = async () => {
    let currentDayScheduleSync = null;
    try {
      currentDayScheduleSync = await syncCurrentDayFightersSchedule(env, now);
      console.log(`[GAME_SCHEDULE_CURRENT_DAY] status=${currentDayScheduleSync.status} date=${currentDayScheduleSync.date || ""} changed=${currentDayScheduleSync.status === "success_changed"}`);
    } catch (error) {
      currentDayScheduleSync = {
        status: "failed",
        date: getJstDateString(now),
        errorCode: error?.code || "CURRENT_DAY_SCHEDULE_SYNC_FAILED",
        lastScheduleSyncAt: now.toISOString()
      };
      console.warn(`[GAME_SCHEDULE_CURRENT_DAY] status=failed date=${currentDayScheduleSync.date || ""} code=${currentDayScheduleSync.errorCode}`);
    }

    let scheduleSync = null;
    try {
      scheduleSync = await ensureFutureFightersSchedule(env, now);
      console.log(`[GAME_SCHEDULE_BUFFER] before=${scheduleSync.futureGamesBefore} after=${scheduleSync.futureGamesAfter} fetched=${scheduleSync.gamesFetched} inserted=${scheduleSync.gamesInserted} updated=${scheduleSync.gamesUpdated} range=${scheduleSync.fetchRangeStart || ""}..${scheduleSync.fetchRangeEnd || ""} skip=${scheduleSync.skipReason || ""}`);
    } catch (error) {
      scheduleSync = {
        status: "failed",
        syncNeeded: true,
        futureGamesBefore: null,
        futureGamesAfter: null,
        futureGamesTarget: AUTOMATION_MIN_FUTURE_GAMES,
        gamesFetched: 0,
        gamesInserted: 0,
        gamesUpdated: 0,
        fetchRangeStart: "",
        fetchRangeEnd: "",
        expandedTo30Days: false,
        skipReason: error?.code || "SCHEDULE_SYNC_FAILED",
        errorCode: error?.code || "SCHEDULE_FETCH_FAILED",
        lastScheduleSyncAt: now.toISOString()
      };
      console.warn(`[GAME_SCHEDULE_BUFFER] status=failed code=${scheduleSync.skipReason}`);
    }
    let officialCancellation = null;
    try {
      officialCancellation = await reconcileOfficialGameCancellations(env, now, {
        includeHistorical: isV3StorageMaintenanceWindow(now)
      });
    } catch (error) {
      officialCancellation = {
        checked: 0,
        applied: 0,
        skipped: 0,
        failed: 1,
        errorCode: error?.code || "OFFICIAL_CANCELLATION_RECONCILE_FAILED"
      };
      console.warn(`[GAME_OFFICIAL_CANCELLATION] status=failed code=${officialCancellation.errorCode}`);
    }
    try {
      await writeScheduleSyncAudit(scheduleSync);
    } catch (error) {
      console.error(`[GAME_SCHEDULE_BUFFER] audit_write_failed code=${error?.code || "SCHEDULE_SYNC_AUDIT_WRITE_FAILED"}`);
    }
    scheduleSync.currentDay = currentDayScheduleSync;
    scheduleSync.officialCancellation = officialCancellation;
    return scheduleSync;
  };

  const summarizePlanResult = (planResult) => ({
    created: Number(planResult?.created || 0),
    planned: Array.isArray(planResult?.planned) ? planResult.planned.length : 0,
    errors: Array.isArray(planResult?.errors) ? planResult.errors.length : 0,
    entries: (Array.isArray(planResult?.planned) ? planResult.planned : []).slice(0, 100).map((entry) => ({
      internalGameId: entry?.game?.internalGameId || entry?.job?.internal_game_id || null,
      jobType: entry?.plan?.jobType || entry?.job?.job_type || entry?.diagnostic?.jobType || null,
      dueAt: entry?.plan?.scheduledAt?.toISOString?.() || entry?.plan?.scheduledAt || entry?.job?.scheduled_at || null,
      action: entry?.created ? "created" : "observed",
      skipReason: entry?.reasonCode || entry?.diagnostic?.reasonCode || null,
      createdJobId: entry?.job?.id || null
    })),
    errorReasons: (Array.isArray(planResult?.errors) ? planResult.errors : []).slice(0, 20).map((entry) => ({
      internalGameId: entry?.game?.internalGameId || null,
      reasonCode: entry?.error?.code || entry?.error?.message || "PLANNER_ERROR"
    }))
  });

  const operationalMode = getV3OperationalMode(env);
  const result = await runGameAutomationV3(env, now, {
    // A free/low-CPU Worker invocation must reach the deadline job before
    // hydrating every historical unfinished game.  Current-day due games are
    // processed first; the next Cron tick drains the remaining window.
    gameListOptions: auxiliaryOnly
      ? { limit: V3_AUXILIARY_GAME_BATCH_SIZE, prioritizeDue: true }
      : { limit: V3_CRON_GAME_BATCH_SIZE, prioritizeDue: true },
    // Auxiliary polling needs the current and next calendar day's games, while
    // an unbounded historical scan can exceed the per-invocation CPU budget.
    // Keep this batch independent from the four-game formal critical path.
    auxiliaryGameListOptions: auxiliaryOnly
      ? null
      : { limit: V3_AUXILIARY_GAME_BATCH_SIZE, prioritizeDue: true },
    executeJob: (context) => operationalMode.disabledJobTypes.includes(String(context?.job?.job_type || ""))
      ? {
        status: "skipped",
        reasonCode: "V4_AUTO_FETCH_DISABLED",
        stateBefore: null,
        stateAfter: null
      }
      : executeGameAutomationV3Job({ ...context, v4SemiAuto: operationalMode.isV4SemiAuto }),
    formalPlanner: (db, games, plannerNow) => planMainWorkflowJobs(db, games, plannerNow, {
      disabledStages: operationalMode.disabledJobTypes,
      v4SemiAuto: operationalMode.isV4SemiAuto
    }),
    auxiliaryPlanner: (db, games, plannerNow) => planAuxiliaryJobs(db, games, plannerNow, {
      autoProbableStarter: operationalMode.autoProbableStarter,
      autoRosterFetch: operationalMode.autoRosterFetch
    }),
    disabledJobTypes: operationalMode.disabledJobTypes,
    v4SemiAuto: operationalMode.isV4SemiAuto,
    runAuxiliary: !criticalOnly,
    auxiliaryOnly,
    skipFormalDiscoveryIfIdle: criticalOnly,
    scheduleOptional,
    observerScheduler,
    onPhase: async (phase) => {
      // Console checkpoints are intentionally separate from D1 audit writes:
      // they keep routine observability available without adding one audit row
      // per phase to every minute's Cron invocation. If the Worker is stopped
      // by a CPU limit, the last emitted checkpoint identifies the boundary
      // reached before termination.
      logV3PhaseCheckpoint(runId, phase, now);
      const eventTypeByStage = {
        eligible_games: "V3_ELIGIBLE_GAMES",
        post_eligible_started: "V3_POST_ELIGIBLE_PHASE_STARTED",
        formal_plan_input_started: "V3_FORMAL_PLAN_INPUT_STARTED",
        formal_plan_input_finished: "V3_FORMAL_PLAN_INPUT_FINISHED",
        formal_plan_input_error: "V3_FORMAL_PLAN_INPUT_ERROR",
        state_prepare_started: "V3_STATE_PREPARATION_STARTED",
        state_prepare_finished: "V3_STATE_PREPARATION_FINISHED",
        reconciliation_started: "V3_RECONCILIATION_STARTED",
        reconciliation_finished: "V3_RECONCILIATION_FINISHED",
        formal_plan_started: "V3_FORMAL_PLAN_STARTED",
        formal_plan_finished: "V3_FORMAL_PLAN_FINISHED",
        formal_plan_error: "V3_FORMAL_PLAN_ERROR",
        formal_due_plan_summary: "V3_FORMAL_DUE_PLAN_SUMMARY",
        auxiliary_plan_started: "V3_AUXILIARY_PLAN_STARTED",
        auxiliary_plan_finished: "V3_AUXILIARY_PLAN_FINISHED",
        auxiliary_plan_summary: "V3_AUXILIARY_PLAN_SUMMARY",
        claim_phase_started: "V3_CLAIM_PHASE_STARTED",
        claim_execution_completed: "V3_CLAIM_EXECUTION_SUMMARY",
        run_finished: "V3_RUN_FINISHED"
      };
      const execution = { ...phase };
      if (phase.stage === "formal_plan_finished" || phase.stage === "formal_plan_error" || phase.stage === "formal_due_plan_summary" || phase.stage === "auxiliary_plan_finished" || phase.stage === "auxiliary_plan_summary") {
        execution.plan = summarizePlanResult(phase.plan);
      }
      if (phase.stage === "claim_execution_completed") {
        const claimReport = phase.claimReport || {};
        execution.claimReport = {
          due: Array.isArray(claimReport.due) ? claimReport.due.length : 0,
          claimed: Array.isArray(claimReport.claimed) ? claimReport.claimed.length : 0,
          skipped: Array.isArray(claimReport.skipped) ? claimReport.skipped.length : 0,
          hasMoreDue: claimReport.hasMoreDue === true,
          claimedJobIds: (Array.isArray(claimReport.claimed) ? claimReport.claimed : []).slice(0, 100).map((entry) => entry?.job?.id || null).filter(Boolean),
          skippedJobIds: (Array.isArray(claimReport.skipped) ? claimReport.skipped : []).slice(0, 100).map((entry) => entry?.job?.id || null).filter(Boolean),
          results: (Array.isArray(claimReport.claimed) ? claimReport.claimed : []).slice(0, 100).map((entry) => ({
            jobId: entry?.job?.id || null,
            result: entry?.claimResult || null,
            errorCode: entry?.claimError?.code || null
          }))
        };
        execution.executionSummary = {
          processed: Number(phase.execution?.processed || 0),
          failed: Number(phase.execution?.failed || 0),
          retryWait: Number(phase.execution?.retryWait || 0),
          terminalFailed: Number(phase.execution?.terminalFailed || 0),
          failedJobIds: Array.isArray(phase.execution?.failedJobIds) ? phase.execution.failedJobIds.slice(0, 100) : [],
          retryErrors: Array.isArray(phase.execution?.retryErrors) ? phase.execution.retryErrors.slice(0, 20) : []
        };
      }
      const eventType = eventTypeByStage[phase.stage] || "V3_PHASE";
      // Routine phase details are already emitted as bounded console
      // checkpoints and are intentionally excluded from persisted audit
      // history. Avoid constructing/scheduling a no-op audit write on every
      // minute when only observability is needed; error phases still persist.
      if (shouldPersistV3Audit({ eventType, execution })) {
        await writeV3RuntimeAudit(env, {
          eventType,
          runId,
          correlationId,
          now,
          execution
        });
      }
    },
    onPlan: async ({ game, plan, job, created, reasonCode, insertedRowCount, existingJobId, existingScheduledSlotAt, existingStatus, diagnostic, plannerDecision = null, stage = "v3_plan", claimResult = null }) => {
      const jobTypeByPlanStage = {
        probable_plan: "probable_starter_fetch",
        roster_plan: "roster_fetch",
        identity_plan: "npb_identity_resolve"
      };
      const jobType = String(
        plan?.jobType
        || job?.job_type
        || plannerDecision?.jobType
        || diagnostic?.jobType
        || jobTypeByPlanStage[stage]
        || "legacy_or_unclassified"
      );
      const phaseByJobType = {
        probable_starter_fetch: "probable_starter",
        roster_fetch: "roster",
        prediction_close: "prediction_close",
        lineup_fetch: "lineup_fetch",
        lineup_finalize: "lineup_finalize",
        score: "score",
        ranking_rebuild: "ranking",
        publish: "publish"
      };
      const phase = phaseByJobType[jobType] || "";
      const normalizedStatus = phase ? deriveV3PhaseStatus({
        phase,
        game,
        now,
        workflowState: "scheduled",
        jobs: job ? [job] : [],
        snapshot: phase === "roster" ? {
          exists: diagnostic?.freshSnapshotExists,
          isFresh: diagnostic?.freshSnapshotExists,
          isStale: diagnostic?.staleSnapshotExists,
          staleReason: diagnostic?.staleReason
        } : null,
        noticeState: diagnostic?.noticeState || null
      }) : null;
      const isClaimAudit = stage.endsWith("_claim");
      const isRoster = jobType === "roster_fetch";
      const isProbable = jobType === "probable_starter_fetch";
      const eventType = isClaimAudit
        ? (isRoster ? "roster_job_claimed" : isProbable ? "probable_starter_job_claimed" : "v3_job_claimed")
        : created
          ? (isRoster ? "roster_job_created" : isProbable ? "workflow_job_created" : "v3_job_created")
          : (isRoster ? "roster_job_plan_observed" : isProbable ? "probable_starter_job_plan_observed" : "v3_job_plan_observed");
      await writeAudit({
        eventType,
        job: {
          ...(job || {}),
          internal_game_id: job?.internal_game_id || game?.internalGameId || null,
          job_type: jobType,
          scheduled_slot_at: plan?.scheduledSlotAt?.toISOString?.() || job?.scheduled_slot_at || null,
          status: claimResult === "claimed" ? "claimed" : (created ? "pending" : existingStatus || job?.status || "observed")
        },
        execution: {
          status: isClaimAudit ? "claimed" : (created ? "created" : "observed"),
          reasonCode: created ? null : reasonCode,
          planningDiagnostics: diagnostic || null,
          insertedRowCount: Number(insertedRowCount || 0),
          actualJobExists: Boolean(job?.id),
          existingJobId: existingJobId || null,
          existingScheduledSlotAt: existingScheduledSlotAt || null,
          existingStatus: existingStatus || null,
          claimResult: claimResult || diagnostic?.claimResult || "not_attempted",
          uniqueKey: "internal_game_id|job_type|scheduled_slot_at",
          runId,
          correlationId,
          stage,
          plannerDecision,
          normalizedStatus: normalizedStatus?.structuredLogFacts || null
        },
        occurredAt: now
      });
    },
    onSuccess: async ({ job, claimToken, result: execution, now: completedAt }) => {
      try {
        const auditExecution = { ...(execution || {}) };
        // The full roster is already persisted in the snapshot. Keep the audit
        // payload compact so source/snapshot diagnostics remain parseable.
        delete auditExecution.roster;
        await writeAudit({ job, claimToken, execution: { ...auditExecution, runId, correlationId, stage: "executor_completed" }, occurredAt: job?.completed_at || job?.updated_at || completedAt });
      } catch (error) {
        console.error(`[GAME_AUTOMATION_V3] audit_write_failed code=${error?.code || "V3_AUDIT_WRITE_FAILED"}`);
      }
    },
    onError: async (error, context) => {
      const id = String(context?.job?.internal_game_id || context?.game?.internalGameId || "");
      console.error(`[GAME_AUTOMATION_V3] internalGameId=${id} stage=${context?.stage || "unknown"} code=${error?.code || "V3_JOB_FAILED"}`);
      if (env.AUTH_DB && id) {
        try {
          let execution = null;
          if (String(context?.job?.job_type || "") === "probable_starter_fetch") {
            const row = await readProbableStarterRow(env.AUTH_DB, { internalGameId: id }).catch(() => null);
            execution = { probableStarter: serializeProbableStarterRow(row) };
          }
          await writeAudit({
            job: context?.job || (id ? { internal_game_id: id, job_type: context?.plan?.jobType || "planner", status: "failed" } : null),
            internalGameId: id,
            claimToken: context?.claimToken,
            stateBefore: context?.stateBefore || "claimed",
            execution: { ...(execution || {}), runId, correlationId, stage: context?.stage || "execute", executorStage: context?.stage || "execute" },
            failure: error,
            occurredAt: context?.job?.updated_at || now
          });
        } catch (auditError) {
          console.error(`[GAME_AUTOMATION_V3] audit_write_failed code=${auditError?.code || "V3_AUDIT_WRITE_FAILED"}`);
        }
      }
     }
  }).catch(async (error) => {
    await writeV3FatalRunAudits({
      writeRuntimeAudit: (payload) => writeV3RuntimeAudit(env, payload),
      writeCriticalPathFinished,
      writeHandlerFinished: writeCronHandlerFinished,
      runId,
      correlationId,
      now,
      error
    });
    const anchor = await env.AUTH_DB.prepare(
      `SELECT internal_game_id FROM games WHERE internal_game_id IS NOT NULL AND internal_game_id <> '' ORDER BY game_date, start_time, internal_game_id LIMIT 1`
    ).first().catch(() => null);
    if (anchor?.internal_game_id) {
      await writeAudit({
        eventType: "cron_run_failed",
        internalGameId: anchor.internal_game_id,
        job: { internal_game_id: anchor.internal_game_id, job_type: "cron_run", status: "failed" },
        execution: { runId, correlationId, stage: "cron_run", errorCode: error?.code || "V3_CRON_RUN_FAILED", errorMessage: error?.message || "V3 Cron failed" },
        failure: error,
        occurredAt: now
      }).catch((auditError) => console.error(`[GAME_AUTOMATION_V3] stage=cron_run_failed_audit code=${auditError?.code || "V3_AUDIT_WRITE_FAILED"}`));
    }
    throw error;
  });
  try {
  if (!auxiliaryOnly) await writeCriticalPathFinished("completed", {
      createdJobCount: Number(result?.created || 0),
      executedJobCount: Number(result?.processed || 0),
      failedJobCount: Number(result?.failed || 0),
      retryWaitJobCount: Number(result?.retryWait || 0),
      terminalFailedJobCount: Number(result?.terminalFailed || 0),
      hasMoreDue: result?.claimReport?.hasMoreDue === true
    });
  if (criticalOnly) {
    logV3PhaseCheckpoint(runId, {
      stage: "schedule_sync_skipped",
      now,
      status: "skipped",
      reasonCode: "CRON_MODE_CRITICAL"
    }, now);
    await writeCronHandlerFinished("completed", {
      cronMode: "critical",
      idleFastPath: result?.idleFastPath === true,
      processedJobCount: Number(result?.processed || 0)
    });
    return {
      ...result,
      scheduleSync: { status: "skipped", pending: false, skipReason: "CRON_MODE_CRITICAL" },
      runId,
      correlationId
    };
  }
  let scheduleSync = null;
  if (typeof scheduleOptional === "function" && shouldRunV3ScheduleSync(now)) {
    const scheduleSyncPromise = Promise.resolve().then(() => {
      logV3PhaseCheckpoint(runId, { stage: "schedule_sync_started", now, status: "started" }, now);
      return runScheduleSync();
    }).then((result) => {
      logV3PhaseCheckpoint(runId, { stage: "schedule_sync_finished", now, status: result?.status || "completed" }, now);
      return result;
    }).catch(async (error) => {
      logV3PhaseCheckpoint(runId, { stage: "schedule_sync_finished", now, status: "failed" }, now);
      await writeV3RuntimeAudit(env, {
        eventType: "V3_SCHEDULE_SYNC_ERROR",
        runId,
        correlationId,
        now,
        execution: { stage: "schedule_sync", errorReason: error?.code || error?.message || "SCHEDULE_SYNC_FAILED" },
        failure: error
      });
      return { status: "failed", errorCode: error?.code || "SCHEDULE_SYNC_FAILED" };
    });
    scheduleOptional(scheduleSyncPromise);
    scheduleSync = { status: "scheduled", pending: true };
  } else if (typeof scheduleOptional === "function") {
    scheduleSync = { status: "skipped", pending: false, skipReason: "SCHEDULE_SYNC_CADENCE" };
    logV3PhaseCheckpoint(runId, { stage: "schedule_sync_skipped", now, status: "skipped", reasonCode: "SCHEDULE_SYNC_CADENCE" }, now);
  } else {
    scheduleSync = await runScheduleSync();
  }
  // Keep cleanup out of the critical path and run it only at the hourly JST
  // boundary. The persisted maintenance keys make the work once per day even
  // when more than one scheduler invocation reaches that boundary.
  if (env.AUTH_DB && isV3StorageMaintenanceWindow(now)) {
    logV3PhaseCheckpoint(runId, { stage: "maintenance_started", now, status: "started" }, now);
    const maintenancePromise = runV3StorageMaintenance(env.AUTH_DB, getV3AuditDb(env), now)
      .then((result) => {
        logV3PhaseCheckpoint(runId, { stage: "maintenance_finished", now, status: result?.status || "completed" }, now);
        return result;
      });
    if (typeof scheduleOptional === "function") scheduleOptional(maintenancePromise);
    else await maintenancePromise;
  }
  let lineupShadow = { status: "disabled" };
  if (isLineupShadowEnabled(env)) {
    const lineupShadowPromise = Promise.resolve()
      .then(() => runLineupShadowForGames(env, now, { runId }))
      .catch((error) => {
        console.warn(`[LINEUP_SHADOW] status=failed code=${error?.code || "LINEUP_SHADOW_FAILED"}`);
        return { status: "failed", errors: 1, reasonCode: error?.code || "LINEUP_SHADOW_FAILED" };
      });
    if (typeof scheduleOptional === "function") {
      scheduleOptional(lineupShadowPromise);
      lineupShadow = { status: "scheduled", pending: true };
    } else {
      lineupShadow = await lineupShadowPromise;
    }
  }
  if (!result?.optionalScheduled) {
    await writeV3RuntimeAudit(env, {
      eventType: "V3_AUXILIARY_PLAN_SUMMARY",
      runId,
      correlationId,
      now,
      execution: {
        stage: "auxiliary_planner_summary",
        probableStarter: summarizePlanResult(result?.probablePlan),
        roster: summarizePlanResult(result?.rosterPlan),
        identity: summarizePlanResult(result?.identityPlan),
        errors: Number(result?.auxiliaryPlan?.errors?.length || 0)
      }
    });
  }
  let workflowStates = [];
  try {
    const gameIds = Array.isArray(result?.gameIds) ? result.gameIds.filter(Boolean).slice(0, 100) : [];
    if (gameIds.length) {
      const placeholders = gameIds.map((_, index) => `?${index + 1}`).join(", ");
      const stateResult = await env.AUTH_DB.prepare(
        `SELECT internal_game_id, state, updated_at FROM game_automation_v3_state WHERE internal_game_id IN (${placeholders})`
      ).bind(...gameIds).all();
      workflowStates = stateResult.results || [];
    }
  } catch (error) {
    console.warn(`[GAME_AUTOMATION_V3] runtime_state_read_failed code=${error?.code || "V3_STATE_READ_FAILED"}`);
  }
  await writeV3RuntimeAudit(env, {
    eventType: "V3_EXECUTION_SUMMARY",
    runId,
    correlationId,
    now,
    execution: {
      stage: "execution_summary",
      createdJobCount: Number(result?.created || 0),
      executedJobCount: Number(result?.processed || 0),
      failedJobCount: Number(result?.failed || 0),
      retryWaitJobCount: Number(result?.retryWait || 0),
      terminalFailedJobCount: Number(result?.terminalFailed || 0),
      failedJobIds: Array.isArray(result?.failedJobIds) ? result.failedJobIds.slice(0, 100) : [],
      retryErrors: Array.isArray(result?.retryErrors) ? result.retryErrors.slice(0, 20) : [],
      hasMoreDue: result?.claimReport?.hasMoreDue === true,
      workflowStateUpdates: result?.stateReconciliation || null,
      workflowStates,
      publishedReached: workflowStates.some((row) => String(row?.state || "") === "published")
    }
  });
  const summary = buildV3CronSummary({
    runId,
    correlationId,
    startedAt: now,
    completedAt: new Date(),
    result,
    scheduleSync
  });
  const anchor = await env.AUTH_DB.prepare(
    `SELECT internal_game_id FROM games WHERE internal_game_id IS NOT NULL AND internal_game_id <> '' ORDER BY game_date, start_time, internal_game_id LIMIT 1`
  ).first().catch(() => null);
  if (anchor?.internal_game_id) {
    await writeAudit({
      eventType: "cron_run_summary",
      internalGameId: anchor.internal_game_id,
      job: { internal_game_id: anchor.internal_game_id, job_type: "cron_run", status: summary.status },
      execution: summary,
      occurredAt: new Date(summary.completedAt)
    }).catch((error) => console.error(`[GAME_AUTOMATION_V3] stage=cron_run_summary_audit code=${error?.code || "V3_AUDIT_WRITE_FAILED"}`));
  }
  if (result?.schemaReady === false) {
    console.error(`[GAME_AUTOMATION_V3] enabled=true code=${result.errorCode}`);
  }
  // Alert delivery is an isolated, bounded side effect.  It is scheduled
  // after the formal summary so Web Push configuration or delivery failures
  // cannot delay or change the game workflow.
  const adminAlertTask = scheduleAdminAlertEvaluation(env, now, result, observerScheduler);
  if (typeof observerScheduler !== "function") await adminAlertTask;
  await writeCronHandlerFinished("completed", { publishedReached: workflowStates.some((row) => String(row?.state || "") === "published") });
  return { ...result, scheduleSync, runId, correlationId, summary };
  } catch (error) {
    await writeV3FatalRunAudits({
      writeRuntimeAudit: (payload) => writeV3RuntimeAudit(env, payload),
      writeCriticalPathFinished,
      writeHandlerFinished: writeCronHandlerFinished,
      runId,
      correlationId,
      now,
      error
    });
    throw error;
  }
}

async function reconcileOfficialGameCancellations(env, now, { includeHistorical = false } = {}) {
  const summary = { checked: 0, applied: 0, skipped: 0, failed: 0, gameIds: [], errors: [] };
  const games = await listOfficialCancellationCandidates(env.AUTH_DB, now, {
    includeHistorical,
    lookbackDays: 2,
    lookaheadDays: 2,
    limit: 50
  });
  for (const game of games) {
    const status = String(game?.gameStatus || "").trim().toLowerCase();
    if (!["cancelled", "postponed", "no_game", "service_unavailable"].includes(status)) continue;
    summary.checked += 1;
    const state = String(game.workflowState || "");
    if (!state || state === "excluded") {
      summary.skipped += 1;
      continue;
    }
    try {
      const result = await applyOfficialGameCancellation(env, game, state, now);
      if (result?.status === "applied") {
        summary.applied += 1;
        summary.gameIds.push(game.internalGameId);
      } else {
        summary.skipped += 1;
      }
    } catch (error) {
      summary.failed += 1;
      summary.errors.push({ internalGameId: game.internalGameId, code: error?.code || "OFFICIAL_CANCELLATION_FAILED" });
      console.warn(`[GAME_OFFICIAL_CANCELLATION] internalGameId=${game.internalGameId} status=failed code=${error?.code || "OFFICIAL_CANCELLATION_FAILED"}`);
    }
  }
  return summary;
}

async function applyOfficialGameCancellation(env, game, stateBefore, now, { statusOverride = null } = {}) {
  const internalGameId = String(game?.internalGameId || "").trim();
  if (!internalGameId) return { status: "skipped", reason: "missing_internal_game_id" };
  const currentLineup = await getGameLineup(env.AUTH_DB, { gameId: internalGameId, internalGameId });
  if (stateBefore === "published" || currentLineup?.published_at) {
    throw createV3Error("OFFICIAL_CANCELLATION_REQUIRES_ADMIN_REVIEW", "公開済み試合の中止は自動変更せず、管理者確認が必要です。", { retryable: false });
  }
  const reflection = await getV3RankingReflectionAudit(env.AUTH_DB, internalGameId);
  if ((stateBefore === "ranked" || reflection.hasReflectedRevision) && !reflection.available) {
    throw createV3Error("OFFICIAL_CANCELLATION_REQUIRES_ADMIN_REVIEW", "ランキング反映履歴を確認できないため、公式中止を自動反映できません。", { retryable: true });
  }
  const context = await loadV3AdminContext(env.AUTH_DB, internalGameId);
  const normalizedStatus = normalizeExternalGameStatus(statusOverride || game.gameStatus || "cancelled");
  const requestedStatus = ["cancelled", "postponed", "no_game", "service_unavailable"].includes(normalizedStatus)
    ? normalizedStatus
    : "cancelled";
  const reason = requestedStatus === "service_unavailable"
    ? "NPB公式情報でサービス対象外状態を確認したため自動反映"
    : requestedStatus === "postponed"
      ? "NPB公式情報で試合延期を確認したため自動反映"
      : requestedStatus === "no_game"
        ? "NPB公式情報でノーゲームを確認したため自動反映"
        : "NPB公式情報で試合中止を確認したため自動反映";
  const scheduleMutation = await applyScheduleChange(env.AUTH_DB, {
    internalGameId,
    proposedSchedule: {
      startAt: context.target.start_time,
      gameDate: context.target.game_date,
      homeTeam: context.target.home_team,
      awayTeam: context.target.away_team,
      status: requestedStatus,
      npbGameCode: context.target.gameCode || "",
      stadium: context.target.stadium || ""
    },
    derivedSchedule: deriveScheduleArtifacts(context.target.start_time),
    actor: "npb-official",
    source: "cron",
    reason,
    officialCorrection: true,
    now
  });
  if (scheduleMutation.status === "skipped") {
    throw createV3Error("OFFICIAL_CANCELLATION_REQUIRES_ADMIN_REVIEW", "公式中止を自動反映できない状態です。", { retryable: false });
  }
  const rankingState = await getRankingGameState(env.AUTH_DB, context.metadata.gameId);
  const eligibility = rankingState
    ? await applyEligibilityChange({
      db: env.AUTH_DB,
      gameId: context.metadata.gameId,
      internalGameId,
      status: RANKING_ELIGIBILITY_STATUS.EXCLUDED,
      gameStatus: requestedStatus,
      reason: requestedStatus === "service_unavailable" ? "service_unavailable" : requestedStatus === "postponed" ? "postponed" : requestedStatus === "no_game" ? "no_game_after_start" : "cancelled_after_start",
      note: reason,
      actor: "npb-official",
      source: "cron",
      officialCorrection: true,
      now,
      persist: (change) => setRankingEligibility(env.AUTH_DB, {
        ...change,
        reflectionStatus: reflection.hasReflectedRevision ? "revoked" : "excluded"
      })
    })
    : { status: "skipped", noOp: true, reason: "RANKING_GAME_NOT_FOUND" };
  const cancelledJobs = await cancelOpenV3Jobs(env.AUTH_DB, internalGameId, reason);
  const transitioned = await transitionV3State(env.AUTH_DB, { internalGameId, from: stateBefore, to: "excluded", now });
  await recordV3AdminAudit(getV3AuditDb(env), {
    internalGameId,
    jobType: "system:official_cancellation",
    stateBefore,
    stateAfter: transitioned?.state || "excluded",
    failureMessage: `[v3_details=${JSON.stringify({ source: "npb_official", status: requestedStatus, reason, cancelledJobs, rankingReflection: reflection })}]`,
    occurredAt: now
  });
  await recordWorkflowLog(env.AUTH_DB, {
    eventType: "official_game_cancelled",
    status: "success",
    gameId: context.metadata.gameId,
    occurredAt: now,
    message: reason,
    metadata: { internalGameId, status: requestedStatus, cancelledJobs, source: "npb_official" },
    source: "system"
  }).catch(() => {});
  return { status: "applied", stateAfter: transitioned?.state || "excluded", gameStatus: requestedStatus, cancelledJobs, scheduleMutation, eligibility };
}

async function loadV3GameTarget(db, internalGameId) {
  const id = normalizeV3InternalGameId(internalGameId);
  let gameColumns = new Set();
  try {
    gameColumns = await getTableColumnSet(db, "games");
  } catch {
    gameColumns = new Set();
  }
  const optionalGameColumns = ["stadium", "npb_game_url", "source_schedule_key", "npb_identity_status", "npb_identity_resolved_at", "npb_identity_source"]
    .filter((column) => gameColumns.has(column));
  const identityColumns = optionalGameColumns;
  const updatedAtColumn = gameColumns.has("updated_at") ? ", updated_at" : "";
  const row = await db.prepare(
    `SELECT internal_game_id, game_date, start_time, home_team, away_team,
            npb_game_code${identityColumns.length ? `, ${identityColumns.join(", ")}` : ""},
            game_status, is_active, deleted_at${updatedAtColumn}
       FROM games WHERE internal_game_id = ?1 LIMIT 1`
  ).bind(id).first();
  if (!row) throw createV3Error("V3_GAME_NOT_REGISTERED", "V3対象試合が日程DBに登録されていません。");
  const hydrated = await hydrateV3GameIdentityFromIdentifiers(db, {
    ...row,
    internalGameId: id,
    gameDate: row.game_date,
    startAt: row.start_time,
    npbGameCode: row.npb_game_code,
    npbGameUrl: row.npb_game_url,
    sourceScheduleKey: row.source_schedule_key,
    npbIdentityStatus: row.npb_identity_status,
    npbIdentityResolvedAt: row.npb_identity_resolved_at,
    npbIdentitySource: row.npb_identity_source
  });
  return {
    ...row,
    internalGameId: row.internal_game_id,
    startAt: row.start_time,
    gameStatus: row.game_status,
    isActive: row.is_active,
    deletedAt: row.deleted_at,
    updatedAt: row.updated_at || null,
    // V3 operations use the canonical UUID as their only game reference.
    // Historical identifiers remain readable through the retired readers.
    gameId: id,
    legacyGameId: "",
    gameCode: hydrated.npbGameCode || "",
    npbGameUrl: hydrated.npbGameUrl || "",
    sourceScheduleKey: hydrated.sourceScheduleKey || "",
    npbIdentityStatus: hydrated.npbIdentityStatus || (hydrated.npbGameCode ? "resolved" : "unresolved"),
    npbIdentityResolvedAt: hydrated.npbIdentityResolvedAt || null,
    npbIdentitySource: hydrated.npbIdentitySource || "",
    targetResolution: "v3_games_internal_game_id"
  };
}

function createV3LineupIdentity(target) {
  const startAt = new Date(target?.startAt || target?.start_time || "");
  const gameCode = normalizeNpbGameCode(target?.gameCode || target?.npb_game_code);
  const sourceUrl = String(target?.npbGameUrl || "").trim() || buildNpbGameUrl(target?.game_date, gameCode);
  if (!INTERNAL_GAME_ID_PATTERN.test(String(target?.internalGameId || "")) || Number.isNaN(startAt.getTime()) || !gameCode || !sourceUrl) return null;
  return {
    internalGameId: target.internalGameId,
    gameId: target.internalGameId,
    gameCode,
    sourceUrl,
    startAt,
    finalLineupFetchAt: new Date(startAt.getTime() + 2 * 60 * 1000),
    game: {
      gameId: target.internalGameId,
      internalGameId: target.internalGameId,
      gameCode,
      npbScoreUrl: sourceUrl,
      date: target.game_date,
      startAt,
      homeTeam: target.home_team,
      awayTeam: target.away_team,
      venue: target.venue || target.stadium || "",
      status: target.game_status
    },
    resolvedBy: "v3_games_npb_identity"
  };
}

function getNextV3IdentityRetryAt(now) {
  const timestamp = new Date(now).getTime();
  if (Number.isNaN(timestamp)) return new Date(Date.now() + 10 * 60 * 1000);
  return new Date(Math.floor(timestamp / (10 * 60 * 1000)) * (10 * 60 * 1000) + 10 * 60 * 1000);
}

async function executeV3IdentityResolutionJob(env, internalGameId, now) {
  const response = await handleAdminV3IdentityResolve(null, env, {}, internalGameId, { skipAuth: true, source: "cron" });
  const payload = await response.json().catch(() => ({}));
  if (payload?.ok) {
    return {
      status: payload.noOp ? "already_resolved" : "resolved",
      identityResolved: true,
      failureCode: null,
      failureMessage: null
    };
  }
  const identityState = String(payload?.identityState || "");
  if (identityState === "pending") {
    throw createV3Error(payload?.code || "NPB_IDENTITY_PENDING", payload?.error || "NPB試合識別情報の掲載を待っています。", {
      retryable: true,
      retryAt: getNextV3IdentityRetryAt(now)
    });
  }
  if (identityState === "manual_action_required") {
    throw createV3Error(payload?.code || "NPB_IDENTITY_MANUAL_ACTION_REQUIRED", payload?.error || "NPB試合識別情報の手動確認が必要です。", {
      retryable: true,
      retryAt: getNextV3IdentityRetryAt(now)
    });
  }
  if (identityState === "retry_wait") {
    const error = createV3Error(payload?.code || "NPB_IDENTITY_RETRY_WAIT", payload?.error || "NPB識別情報の掲載を待っています。", {
      retryAt: getNextV3IdentityRetryAt(now)
    });
    throw error;
  }
  throw createV3Error(payload?.code || "NPB_IDENTITY_RESOLUTION_FAILED", payload?.error || "NPB試合識別情報を解決できませんでした。");
}

async function executeV3IdentityExecutor({ env, internalGameId, now, stateBefore }) {
  const result = await executeV3IdentityResolutionJob(env, internalGameId, now);
  return { ...result, stateBefore, stateAfter: stateBefore };
}

