async function handleAdminRanking(request, env, cors, periodType) {
  const access = await requireAdminUser(request, env, cors);
  if (!access.ok) return access.response;

  const options = periodType === "weekly"
    ? parseWeeklyRankingQuery(new URL(request.url).searchParams)
    : periodType === "monthly"
      ? parseMonthlyRankingQuery(new URL(request.url).searchParams)
      : parseYearlyRankingQuery(new URL(request.url).searchParams);
  if (!options.ok) return jsonResponse({ ok: false, error: options.error }, 400, cors);

  const ranking = await getRankingForPeriod(env.AUTH_DB, {
    ...options,
    publishedOnly: true,
    includeTestUsers: true
  });
  const response = jsonResponse({
    ok: true,
    periodType: options.periodType,
    periodKey: options.periodKey,
    ranking: ranking.rows,
    summary: ranking.summary,
    pagination: ranking.pagination,
    updatedAt: new Date().toISOString()
  }, 200, cors);
  response.headers.set("Cache-Control", "private, no-store");
  return response;
}

async function handleGetPerfectAchieversRanking(request, env, cors) {
  const options = parsePerfectAchieversQuery(new URL(request.url).searchParams);
  if (!options.ok) {
    return jsonResponse({ ok: false, error: options.error }, 400, cors);
  }

  // The public release date gates weekly rankings only. Formally published
  // game results remain visible before the weekly ranking program starts.
  const achievers = await getPerfectAchieversForDate(env.AUTH_DB, options);
  const response = jsonResponse({
    ok: true,
    date: options.date,
    achievers: achievers.rows,
    totalCount: achievers.totalCount,
    updatedAt: new Date().toISOString()
  }, 200, cors);
  response.headers.set("Cache-Control", "public, max-age=30");
  return response;
}

async function handleGetDailyBestNine(request, env, cors) {
  const params = new URL(request.url).searchParams;
  // Best Nine is a system-wide published result, not a per-user result. The
  // optional query remains accepted for compatibility, but it is deliberately
  // not used to select a different game so every visitor sees one target.
  void params;
  const latestPublished = await getLatestPublishedRankingGame(env.AUTH_DB, {
    releaseCutoffAt: getPublicRankingStartDate(env)
  });
  if (!latestPublished) {
    return jsonResponse({
      ok: true,
      gameDate: "",
      displayLabel: "",
      published: false,
      gameStatus: "",
      rankingExcluded: false,
      resultAvailability: "unpublished",
      bestNine: [],
      totalCount: 0,
      updatedAt: new Date().toISOString()
    }, 200, cors);
  }

  const requestedGameId = latestPublished.internalGameId || latestPublished.gameId;
  const metadata = await resolvePredictionGameMetadata(env.AUTH_DB, requestedGameId);
  if (!metadata) {
    return jsonResponse({ ok: false, error: "対象試合を確認できません。" }, 404, cors);
  }
  const game = await getResultGameMetadata(env.AUTH_DB, requestedGameId, metadata);
  const internalGameId = String(metadata.internalGameId || game.internalGameId || "").trim();
  const legacyGameId = String(metadata.legacyGameId || game.legacyGameId || metadata.gameId || "").trim();
  const rankingState = await getRankingGameState(env.AUTH_DB, legacyGameId, internalGameId);
  const published = Boolean(rankingState
    && String(rankingState.game_status || "") === "scored"
    && String(rankingState.publication_status || "") === "published"
    && Number(rankingState.is_ranking_eligible || 0) === 1
    && Number(rankingState.is_test_game || 0) === 0);
  const bestNine = published
    ? await getDailyBestNineForGame(env.AUTH_DB, { internalGameId, legacyGameId, limit: DAILY_BEST_NINE_LIMIT })
    : { rows: [], totalCount: 0 };
  const response = jsonResponse({
    ok: true,
    internalGameId,
    gameId: legacyGameId,
    gameDate: game.gameDate || metadata.date || "",
    displayLabel: game.displayLabel || createPublicResultDisplayLabel({ gameDate: game.gameDate || metadata.date, homeTeam: game.homeTeam, awayTeam: game.awayTeam }),
    published,
    gameStatus: rankingState?.game_status || game.gameStatus || "",
    rankingExcluded: Boolean(rankingState && Number(rankingState.is_ranking_eligible || 0) !== 1),
    resultAvailability: published
      ? "published"
      : (rankingState && Number(rankingState.is_ranking_eligible || 0) !== 1 ? "excluded" : "unpublished"),
    bestNine: bestNine.rows,
    totalCount: bestNine.totalCount,
    publishedAt: rankingState?.published_at || latestPublished.publishedAt || null,
    updatedAt: new Date().toISOString()
  }, 200, cors);
  response.headers.set("Cache-Control", "public, max-age=30");
  return response;
}

